sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float bend;
uniform float amount;
uniform float axis;
uniform float centerPos;
uniform float curve;
uniform float skew;
uniform float wobble;
uniform float wobbleSpeed;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 uv = coord / size;
    float t = axis < 0.5 ? uv.x : uv.y;
    float u = (t - centerPos) * 2.0;
    float f = pow(abs(u), curve) * (u < 0.0 ? 1.0 - skew : 1.0 + skew);
    float wob = 1.0 + wobble * sin(time * wobbleSpeed);
    float2 off = axis < 0.5 ? float2(0.0, f * bend * amount * wob) : float2(f * bend * amount * wob, 0.0);
    return fin(c, tex(coord - off), opacity);
}
